<?php
require_once __DIR__.'/../lib/integrations.php';
$config=integrationConfig('nonceblox_mysql');if(($config['status']??'')!=='configured')throw new RuntimeException('NonceBlox source is not configured.');
$remote=new PDO('mysql:host='.$config['host'].';port='.($config['port']?:3306).';dbname='.$config['database'].';charset=utf8mb4',$config['username'],integrationSecret($config,'password'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_TIMEOUT=>8]);$local=db();
$jobs=$remote->query('SELECT id,title,`desc` FROM career')->fetchAll();$find=$local->prepare('SELECT id FROM jobs WHERE title=? LIMIT 1');$addJob=$local->prepare('INSERT INTO jobs(title,description) VALUES(?,?)');foreach($jobs as $job){$find->execute([$job['title']]);if(!$find->fetchColumn())$addJob->execute([$job['title'],$job['desc']]);}
$applicants=$remote->query('SELECT id,fname,lname,email,phone,job_position,`date`,country,file FROM career_request')->fetchAll();$save=$local->prepare("INSERT INTO candidates(id,name,role_title,email,phone,country_name,score,stage,source_name,skills_json,experience_json,analysis_json,stored_file,created_at) VALUES(?,?,?,?,?,?,0,'Applied','NonceBlox website','[]','{}','{}',?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),role_title=VALUES(role_title),email=VALUES(email),phone=VALUES(phone),country_name=VALUES(country_name),stored_file=VALUES(stored_file)");foreach($applicants as $a){$id='WEB-'.substr(hash('sha256','nonceblox-career-'.$a['id']),0,20);$name=trim($a['fname'].' '.$a['lname'])?:'Website applicant';$file=trim((string)$a['file']);if($file!==''&&!filter_var($file,FILTER_VALIDATE_URL))$file='https://nonceblox.com/uploads/'.rawurlencode(basename(str_replace('\\','/',$file)));$created=date('Y-m-d H:i:s',strtotime($a['date']?:'now'));$save->execute([$id,$name,$a['job_position']?:'Candidate',$a['email']?:null,$a['phone']?:null,$a['country']?:null,$file?:null,$created]);}
echo 'jobs_synced='.count($jobs).PHP_EOL.'applicants_synced='.count($applicants).PHP_EOL;
